time_polling_ms = {num_polling_out_comm}*{time_polling_ms};

if(anio.time == null){
    return 0;
}else{
    if(Date.now() - anio.time > time_polling_ms) 
    {
        return 0;
    }
    else 
    {
        return 1;
    }
}

time_polling_ms = {num_polling_out_comm}*{time_polling_ms};

if(anio.time == null){
    return 0;
}else{
    if(Date.now() - anio.time > time_polling_ms) 
    {
        return 0;
    }
    else 
    {
        return 1;
    }
}

var etd = [];

for (ndet = 1; ndet <= 8; ndet++) {
    if(typeof this['velocidad_media_'+ndet] != 'undefined'){
        var det = new Object();

        det.timestamp = this['timestamp_'+ndet].value;
        det.integration_period = this['periodo_integracion_'+ndet].value / 60;
        det.current_direction = this['sentido_circulacion_'+ndet].value;
        det.n_vehicles = this['intensidad_total_'+ndet].value;
        det.occupancy = this['ocupacion_espira_cabeza_'+ndet].value;
        det.congestion = this['deteccion_congestion_'+ndet].value;
        det.kamikaze = this['deteccion_intensidad_inversa_'+ndet].value;
        det.average_speed = this['velocidad_media_'+ndet].value;
        det.average_length = this['longitud_media_'+ndet].value;
        det.gap = this['distancia_media_'+ndet].value;
        det.headway = this['distancia_media_'+ndet].value;
        det.fail_data = this['fallo_datos_'+ndet].value;
        det.veh_length_1 = this['vehlong1_'+ndet].value;
        det.veh_length_2 = this['vehlong2_'+ndet].value;
        det.veh_speed_1 = this['vehvel1_'+ndet].value;
        det.veh_speed_2 = this['vehvel2_'+ndet].value;
        det.veh_speed_3 = this['vehvel3_'+ndet].value;

        etd.push(det);
    }
}

var jsonString = JSON.stringify(etd);

return jsonString;
